{"type":"FlowTopic","triggers":[{"type":"Trigger","name":"3bd594b896a740d889a0471d12540231","triggerType":"request","applicability":{"type":"Applicability","mode":"script","value":"true"},"id":"3bd594b896a740d889a0471d12540231"}],"goals":[{"name":"primary","trigger_id":"3bd594b896a740d889a0471d12540231","nodes":[{"type":"StartGoal","goal_id":"primary","greeting_msg":{"type":"String","mode":"string","value":""},"id":"f16955ef9e724edb9417999db2bd353b","name":"Start","expert_mode":false},{"type":"TerminateGoal","goal_id":"primary","confirmation_msg":{"type":"String","mode":"string","value":""},"id":"a2ee8aecd3184254b755fb5bc409adf4","name":"End","expert_mode":false},{"type":"LibraryCall","library_topic_name":"AI Output","library_topic_id":"fc4c14b2431cc21006650464dbb8f2a9","library_topic_is_template":false,"parameter-mappings":[{"parameter-name":"definition","value":{"type":"String","mode":"script","value":"(function execute() {
 var config = {
 configuration: {"description":"{{0}}"}
 };
 return JSON.stringify(config);
 })()"},"metadata":{"type":"String","list":false,"items":[],"use_items":false}},{"parameter-name":"inputs","metadata":{"type":"String","list":true,"items":[{"type":"String","mode":"string","value":"Display the following success message to the user in a clear and friendly tone:

{{vaInputs.response}},
Success! 🎉 A new badge has been assigned successfully. You're all set to use your badge!

After displaying this message, gracefully end the chat session without asking further questions."}],"use_items":true}}],"return-value-mappings":[],"header_card_fields":[],"input_parameters_mode":"dynamic","output_parameters_mode":"dynamic","id":"1075fc19c99447d3b0e46f6f472f3551","name":"Assign Response","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"ScriptedAction","script":"(function execute() {

 //TODO: in all flows convert inputs to lower case. 
 if(null!= vaInputs.badge_type && ""!= vaInputs.badge_type){
 vaVars.badge_type= vaInputs.badge_type;
 }else{
 vaInputs.badge_type = "";
 vaVars.badge_type= "";
 }

 var idenlocationGr = new GlideRecordSecure('x_aleen_snguardian_identity_location')
 idenlocationGr.addQuery('identity',vaInputs.user_sys_id);
 idenlocationGr.query();
 var location = "";
 if(idenlocationGr.next()){
 location = idenlocationGr.location;
 vaVars.user_location = location;
 }
 //TODO : will use guardian Location administrator config.
 var dtInputs = {};
 dtInputs.user_location = vaVars.user_location;
 var result = new GuardianAIAgentHelper().getDTConfigs("a57ddb4833083650bf1221382e5c7b7e",dtInputs);
 vaVars.location_mobile_cred_enabled = result.mc_support;
 vaVars.mc_system = result.mc_nfc_sysyem;
 vaVars.default_system = result.mc_pac_system;
 vaVars.web_prov = result.web_prov;
 vaVars.default_badge_subtype = result.mc_sub_type;


 //set default system based on user/logged in user location
 var locationAdminGr = new GlideRecordSecure('x_aleen_snguardian_badge_office');
 locationAdminGr.addQuery('locationsLIKE'+vaVars.user_location);
 locationAdminGr.orderBy('order');
 locationAdminGr.query();
 if(locationAdminGr.next()){
 vaVars.default_system = locationAdminGr.system;
 }
})()
","id":"c11a799b86594182b747ec8d0974ff70","name":"Get User Location & Location Config","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"ScriptedAction","script":"(function execute() {
 var badge_type_calculated = "";
 // DON'T CHANGE CODE UNLESS WILLING TO TEST 16 scenarios ::BEGIN.
 var badge_issue_userInput = vaInputs.badge_issue_type;
 if(null == badge_issue_userInput || undefined == badge_issue_userInput){
 badge_issue_userInput= "";
 }else{
 badge_issue_userInput = badge_issue_userInput.toString();
 }
 if(null != badge_issue_userInput && "" != badge_issue_userInput && badge_issue_userInput.indexOf("plastic") > -1){
 if(null != vaInputs.badge_type_input_choice && "" != vaInputs.badge_type_input_choice ){
 badge_type_calculated = vaInputs.badge_type_input_choice.toString();
 } else {
 badge_type_calculated = vaVars.badge_type.toString();
 }
 } else if(null != badge_issue_userInput && "" != badge_issue_userInput && badge_issue_userInput.indexOf("mobile") > -1){
 badge_type_calculated = "mobile credentials";
 } else {
 if(vaVars.badge_type != ""){
 badge_type_calculated = vaVars.badge_type;
 }else{
 badge_type_calculated = vaInputs.badge_type_input_choice;
 }
 }
 vaVars.badge_type = badge_type_calculated;
 gs.info("FINAL BADGE_TYPE ====>" + badge_type_calculated);


 var inputs = {};
 inputs['u_location'] = vaVars.user_location; // Reference, Sys ID of the record 
 inputs['u_employee_type'] = vaInputs.user_type_sys_id.toString(); // Reference, Sys ID of the record 
 inputs['u_badge_type'] = vaVars.badge_type; // String 
 inputs['u_badge_action'] = "assign"; // String 

 var dt = new sn_dt.DecisionTableAPI();
 var response = dt.getDecision('0d37c78833843650bf1221382e5c7bc7', inputs);

 var result_elements = response.result_elements;
 vaVars.dt_res_u_auto_badge_allocation = result_elements.u_auto_badge_allocation.getValue(); // True/False
 vaVars.dt_res_u_create_request = result_elements.u_create_request.getValue(); // True/False
 vaVars.dt_res_u_def_valid_from = result_elements.u_def_valid_from.getValue(); // True/False
 vaVars.dt_res_u_def_valid_to = result_elements.u_def_valid_to.getValue(); // Duration
 vaVars.dt_res_u_def_access = result_elements.u_def_access.getValue(); // True/False

 // Get and assign badge from Asset if dt_res_u_auto_badge_allocation is True(1)
 vaVars.fetched_badge = ""; 
 if(vaVars.dt_res_u_auto_badge_allocation == "1" || vaVars.dt_res_u_auto_badge_allocation == 1 ){
 try{ 
 var metadataGlideRecordHelper = new x_aleen_snguardian.MetadataGlideRecordHelper();
 var badgeTypeCode = "";
 if(vaVars.badge_type.toLowerCase().indexOf("mobile")>-1 || vaVars.badge_type.toLowerCase().indexOf('credential')>-1){
 badgeTypeCode = "MOBILE_CREDENTIAL";
 }else if(vaVars.badge_type.toLowerCase().indexOf("perm")>-1){
 badgeTypeCode = "PERMANENT_BADGE";
 }else{
 badgeTypeCode = "TEMP_BADGE";
 }
 var badgeTypeSysId = metadataGlideRecordHelper.getRecordSysIdByCode('x_aleen_snguardian_asset_type',badgeTypeCode);

 var assetGr = new GlideRecordSecure('x_aleen_snguardian_asset');
 if(badgeTypeCode=="MOBILE_CREDENTIAL"){
 assetGr.addQuery('system',vaVars.mc_system);
 assetGr.addQuery('sub_system',vaVars.default_system);
 assetGr.addQuery('sub_type',vaVars.default_badge_subtype);
 }else{
 assetGr.addQuery('system',vaVars.default_system);
 }
 assetGr.addQuery('type', badgeTypeSysId);
 assetGr.addQuery('status.code',"UNASSIGNED");
 assetGr.addQuery('is_deleted',false);
 assetGr.query();
 if(assetGr.next()){
 vaVars.fetched_badge = assetGr.getUniqueValue().toString();
 }else if(badgeTypeCode=="MOBILE_CREDENTIAL"){
 var badge_number = (GlideSecureRandomUtil.getSecureRandomIntBound(90000) + 10000).toString();// set random number 5 digit
 var creatAssetGr = new GlideRecordSecure('x_aleen_snguardian_asset');
 creatAssetGr.initialize();
 creatAssetGr.setValue('serial',badge_number);
 creatAssetGr.setValue('system',vaVars.mc_system);
 creatAssetGr.setValue('sub_system',vaVars.default_system);
 creatAssetGr.setValue('sub_type',vaVars.default_badge_subtype);
 creatAssetGr.setValue('status', metadataGlideRecordHelper.getRecordSysIdByCode('x_aleen_snguardian_status_code',"UNASSIGNED"));
 creatAssetGr.setValue('type',badgeTypeSysId);
 var assetSysId = creatAssetGr.insert();
 vaVars.fetched_badge = assetSysId.toString();
 }else{
 gs.info("Empty :::: ");
 vaVars.fetched_badge = ""; 
 }
 }catch(err){
 gs.info("Error in Assign Badge Topic Block => getting Badge DT Config "+err);
 }
 }

 // SET defualt valid from if dt_res_u_def_valid_from is True(1)
 gs.info("Valid From Config : "+vaVars.dt_res_u_def_valid_from);
 if(vaVars.dt_res_u_def_valid_from == "1" || vaVars.dt_res_u_def_valid_from == 1){
 vaVars.valid_from = new GlideDateTime().getDisplayValue();
 vaInputs.badge_valid_from = vaVars.valid_from;
 }

 // default valid to if dt_res_u_def_valid_to is NOT "1970-01-01 00:00:00"
 if( "1970-01-01 00:00:00" != vaVars.dt_res_u_def_valid_to && "" != vaVars.dt_res_u_def_valid_to){
 vaVars.valid_to = new x_aleen_snguardian.TimeZoneUtil().getDurationDifference(vaVars.dt_res_u_def_valid_to, "add");
 vaInputs.badge_valid_to = vaVars.valid_to;
 }


 if( vaVars.dt_res_u_create_request == "0"){
 vaVars.submission_mode = "direct";
 }else{
 // vaVars.submission_mode = "request";
 vaVars.submission_mode = "direct";
 }


})()
